def h(x):
    x=x.strip().strip('"')
    return int(x,16) if x.startswith('0x') else None
# Chainlink USDC/USD latestRoundData
r=""
w=[r[2:][i*64:(i+1)*64] for i in range(5)]
print("USDC/USD roundId",h('0x'+w[0]),"answer",h('0x'+w[1]),"->",h('0x'+w[1])/1e8,"updatedAt",h('0x'+w[3]))
# stETH/ETH
r2=""
w2=[r2[2:][i*64:(i+1)*64] for i in range(5)]
print("stETH/ETH answer",h('0x'+w2[1]),"->",h('0x'+w2[1])/1e18,"updatedAt",h('0x'+w2[3]))
# Aave
sup=h("0x00000000000000000000000000000000000000000000000000087604e335970d")
cash=h("0x00000000000000000000000000000000000000000000000000007ee7d88b1e93")
